import { createContext, useContext, useState, useCallback } from "react";

const Ctx = createContext();

const DEMO_ILANLAR = [
  { id: 1, yuk: "Kömür", nereden: "Antalya", nereye: "İzmir", ton: 22, ucret: 8500, sure: "~7 saat", tarih: "2026-05-06", aracTip: "TIR / Kapalı Kasa", stokToplam: 10, stokKalan: 7, aciklama: "Antalya Liman'dan İzmir OSB'ye kömür. Sabah 08:00 yükleme. Kapalı kasa TIR şart.", teklifSayisi: 3, durum: "aktif", olusturan: "Mevlüt Taşıma A.Ş.", olusturanPuan: 4.8, belgeler: [{ ad: "İrsaliye", ok: true }, { ad: "Tartı Makbuzu", ok: true }, { ad: "Firma Ruhsatı", ok: true }] },
  { id: 2, yuk: "Çelik Boru", nereden: "Ankara", nereye: "Bursa", ton: 18, ucret: 6200, sure: "~5 saat", tarih: "2026-05-07", aracTip: "Flatbed / Lowbed", stokToplam: 5, stokKalan: 4, aciklama: "Flatbed veya lowbed TIR gerekli. Vinçli yükleme yapılacak.", teklifSayisi: 1, durum: "aktif", olusturan: "Kardeşler Çelik Ltd.", olusturanPuan: 4.6, belgeler: [{ ad: "CMR Belgesi", ok: true }, { ad: "Ambalaj Listesi", ok: false }] },
  { id: 3, yuk: "Soğutmalı Gıda", nereden: "İstanbul", nereye: "Gaziantep", ton: 15, ucret: 11000, sure: "~12 saat", tarih: "2026-05-08", aracTip: "Frigorifik TIR", stokToplam: 8, stokKalan: 2, aciklama: "+4°C soğutmalı araç zorunlu. ATP belgeli kamyon şart. Gece vardiyası.", teklifSayisi: 6, durum: "aktif", olusturan: "Metro Gıda Lojistik", olusturanPuan: 4.9, belgeler: [{ ad: "Soğuk Zincir Sertifikası", ok: true }, { ad: "Sıcaklık Kaydı", ok: true }, { ad: "Sağlık Belgesi", ok: true }] },
  { id: 4, yuk: "Meyve (Portakal)", nereden: "Mersin", nereye: "Ankara", ton: 20, ucret: 7800, sure: "~6 saat", tarih: "2026-05-09", aracTip: "Tenteli TIR", stokToplam: 15, stokKalan: 15, aciklama: "Portakal yükü. Havalandırmalı araç tercih edilir. Erken sabah yükleme.", teklifSayisi: 0, durum: "aktif", olusturan: "Akdeniz Tarım A.Ş.", olusturanPuan: 4.7, belgeler: [{ ad: "Gıda Güvenlik Belgesi", ok: true }] },
  { id: 5, yuk: "İnşaat Malzemesi", nereden: "Kocaeli", nereye: "Konya", ton: 25, ucret: 9200, sure: "~4 saat", tarih: "2026-05-10", aracTip: "Damperli TIR", stokToplam: 20, stokKalan: 18, aciklama: "Çakıl ve kum karışık yük. Damperli araç şart. Hafta içi her gün.", teklifSayisi: 2, durum: "aktif", olusturan: "Anadolu İnşaat", olusturanPuan: 4.5, belgeler: [{ ad: "Sevk İrsaliyesi", ok: true }] },
  { id: 6, yuk: "Elektronik Eşya", nereden: "İzmir", nereye: "İstanbul", ton: 8, ucret: 5500, sure: "~6 saat", tarih: "2026-05-11", aracTip: "Kapalı Kasa Kamyon", stokToplam: 3, stokKalan: 3, aciklama: "Hassas elektronik ürünler. Sarsıntısız taşıma şart. Sigorta zorunlu.", teklifSayisi: 0, durum: "aktif", olusturan: "Ege Elektronik", olusturanPuan: 4.3, belgeler: [{ ad: "Sigorta Poliçesi", ok: true }, { ad: "Sevk İrsaliyesi", ok: false }] },
  { id: 7, yuk: "Tekstil", nereden: "Bursa", nereye: "İstanbul", ton: 12, ucret: 4200, sure: "~3 saat", tarih: "2026-05-12", aracTip: "Tenteli TIR", stokToplam: 6, stokKalan: 6, aciklama: "Hazır giyim malı. Su geçirmez kaplama tercih edilir.", teklifSayisi: 0, durum: "aktif", olusturan: "Bursa Tekstil A.Ş.", olusturanPuan: 4.6, belgeler: [{ ad: "İrsaliye", ok: true }] },
];

const DEMO_TEKLIFLER = [
  { id: 1, ilanId: 1, kamyoncuAd: "Mehmet Yılmaz", plaka: "34 TYK 421", teklif: 8200, tarih: "2026-05-03", durum: "bekliyor", puan: 4.9 },
  { id: 2, ilanId: 1, kamyoncuAd: "Ali Kaya", plaka: "06 ALK 99", teklif: 8400, tarih: "2026-05-03", durum: "bekliyor", puan: 4.6 },
  { id: 3, ilanId: 3, kamyoncuAd: "Hasan Tekin", plaka: "34 HSN 07", teklif: 10500, tarih: "2026-05-02", durum: "onaylandı", puan: 4.8 },
  { id: 4, ilanId: 2, kamyoncuAd: "Yusuf Demir", plaka: "35 YDF 21", teklif: 5950, tarih: "2026-05-03", durum: "bekliyor", puan: 4.7 },
];

const DEMO_GECMIS_ISLER = [
  { id: 1, yuk: "Kömür Nakliyesi", nereden: "Antalya", nereye: "İzmir", ucret: 8200, tarih: "2026-04-28", kamyoncu: "Mehmet Yılmaz", plaka: "34 TYK 421", durum: "tamamlandı", belgeler: [{ ad: "İrsaliye_28Nis.pdf", boyut: "124 KB", tarih: "28 Nis 2026" }, { ad: "Makbuz_001.pdf", boyut: "88 KB", tarih: "28 Nis 2026" }] },
  { id: 2, yuk: "Çelik Boru", nereden: "Ankara", nereye: "Bursa", ucret: 6100, tarih: "2026-04-22", kamyoncu: "Ali Kaya", plaka: "06 ALK 99", durum: "tamamlandı", belgeler: [{ ad: "CMR_22Nis.pdf", boyut: "210 KB", tarih: "22 Nis 2026" }] },
  { id: 3, yuk: "Meyve", nereden: "Mersin", nereye: "Ankara", ucret: 7500, tarih: "2026-04-15", kamyoncu: "Hasan Tekin", plaka: "34 HSN 07", durum: "tamamlandı", belgeler: [] },
];

export const AppProvider = ({ children }) => {
  const [oturum, setOturum]         = useState(null);
  const [kullanicilar, setKullanicilar] = useState([]);
  const [ilanlar, setIlanlar]       = useState(DEMO_ILANLAR);
  const [teklifler, setTeklifler]   = useState(DEMO_TEKLIFLER);
  const [gecmisIsler, setGecmisIsler] = useState(DEMO_GECMIS_ISLER);

  // KAYIT OL
  const kayitOl = useCallback((bilgiler) => {
    const yeniKullanici = { ...bilgiler, id: Date.now(), kayitTarihi: new Date().toISOString().split("T")[0], puan: 0, durum: "aktif" };
    setKullanicilar(prev => [...prev, yeniKullanici]);
    setOturum(yeniKullanici);
    return yeniKullanici;
  }, []);

  // GİRİŞ YAP
  const girisYap = useCallback((rol, ad) => {
    setOturum({ rol, ad, id: Date.now(), kayitTarihi: new Date().toISOString().split("T")[0] });
  }, []);

  const cikisYap = useCallback(() => setOturum(null), []);

  // İLAN EKLE (stok dahil)
  const ilanEkle = useCallback((yeni) => {
    const ilan = {
      ...yeni,
      id: Date.now(),
      teklifSayisi: 0,
      durum: "aktif",
      stokKalan: Number(yeni.stokToplam),
      stokToplam: Number(yeni.stokToplam),
      olusturan: oturum?.firmaAdi || oturum?.ad || "Demo Firma",
      olusturanPuan: 5.0,
      belgeler: [],
    };
    setIlanlar(prev => [ilan, ...prev]);
  }, [oturum]);

  const ilanSil = useCallback((id) => setIlanlar(prev => prev.filter(i => i.id !== id)), []);

  // TEKLİF GÜNCELLE + stok azalt
  const teklifGuncelle = useCallback((id, durum) => {
    setTeklifler(prev => prev.map(t => t.id === id ? { ...t, durum } : t));
    if (durum === "onaylandı") {
      const teklif = teklifler.find(t => t.id === id);
      if (teklif) {
        setIlanlar(prev => prev.map(i => i.id === teklif.ilanId
          ? { ...i, stokKalan: Math.max(0, i.stokKalan - 1), teklifSayisi: i.teklifSayisi }
          : i
        ));
      }
    }
  }, [teklifler]);

  // TEKLİF VER
  const teklifEkle = useCallback((yeni) => {
    setTeklifler(prev => [...prev, { ...yeni, id: Date.now(), tarih: new Date().toISOString().split("T")[0] }]);
    setIlanlar(prev => prev.map(i => i.id === yeni.ilanId ? { ...i, teklifSayisi: i.teklifSayisi + 1 } : i));
  }, []);

  // BELGE EKLE (iş veren - geçmiş iş)
  const belgeEkle = useCallback((isId, belge) => {
    setGecmisIsler(prev => prev.map(is => is.id === isId
      ? { ...is, belgeler: [...is.belgeler, { ...belge, tarih: new Date().toLocaleDateString("tr-TR") }] }
      : is
    ));
  }, []);

  const adminKullanicilar = [...kullanicilar,
    { id: 9001, ad: "Mehmet Yılmaz", rol: "kamyoncu", puan: 4.9, durum: "aktif", kayitTarihi: "2024-01-15" },
    { id: 9002, ad: "Metro Gıda Lojistik", rol: "issiz", puan: 4.9, durum: "aktif", kayitTarihi: "2024-02-10" },
  ];

  return (
    <Ctx.Provider value={{
      oturum, kullanicilar: adminKullanicilar, ilanlar, teklifler, gecmisIsler,
      kayitOl, girisYap, cikisYap,
      ilanEkle, ilanSil, teklifGuncelle, teklifEkle, belgeEkle,
    }}>
      {children}
    </Ctx.Provider>
  );
};

export const useApp = () => useContext(Ctx);
